import{_ as c,l as d,o as e,c as i,v as o,p as t,x as s,d as n,i as A,S as l}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"ISA 作为 ABI 边界","description":"","frontmatter":{"title":"ISA 作为 ABI 边界","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/isa-abi-boundary.md","filePath":"cs/isa-abi-boundary.md","lastUpdated":1789023840000}'),B={name:"cs/isa-abi-boundary.md"};function I(p,a,E,h,S,u){const r=d("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="isa-作为-abi-边界" tabindex="-1">ISA 作为 ABI 边界 <a class="header-anchor" href="#isa-作为-abi-边界" aria-label="Permalink to &quot;ISA 作为 ABI 边界&quot;">​</a></h1><div class="epigraph"><p>ISA 保证指令与异常；ABI 保证参数在哪几个寄存器、栈如何对齐、哪份扩展算「这颗用户程序的机器」。越过这条线，合法编码仍无法与 libc 互调。</p><footer>—— 据 System V Application Binary Interface；RISC-V ELF psABI；ARM Procedure Call Standard；Patterson and Hennessy, Computer Organization and Design 整理</footer></div><p><a href="/cs/alignment-access">上一课</a>把自然对齐写成硬件与陷阱。<a href="/cs/calling-convention-stack">调用约定</a> 与<a href="/cs/abi-codegen">代码生成</a> 已在组成/编译课出现过。本单元对照完 x86、ARM、RISC-V 之后，缺口是把这些事实收成 <strong>ABI 边界</strong>：哪些是硅保证的，哪些是软件合同，以免后课微结构把 <code>a0</code> 当成 ISA 强制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ISA：寄存器堆、指令编码、<a href="/cs/fence-instructions">fence</a>、<a href="/cs/sv39-page-table">Sv39</a>、端序、对齐陷阱。ABI：参数前几个进 <code>a0</code>–<code>a7</code> 还是 <code>rdi</code>/<code>rsi</code>，栈 16 字节对齐，浮点/向量寄存器谁保存，结构体如何拆，系统调用号与返回值错误约定。缺口不是再画栈帧，而是<strong>同一 ISA 上可以有多份 ABI</strong>（SysV vs Windows x64；RISC-V ILP32 vs LP64；带不带 <code>C</code>/<code>F</code>/<code>D</code>/<code>V</code>）。</p><p>可执行文件还要 ELF 头、重定位、GOT/PLT；那是加载器合同，比单条 <code>jal</code> 更宽。硬件不读 ELF。把「能在这颗核上跑」等同于「能链上 glibc」，对照课会在动态链接处翻车。</p><h3 id="abi-不是指令子集" tabindex="-1">ABI 不是指令子集 <a class="header-anchor" href="#abi-不是指令子集" aria-label="Permalink to &quot;ABI 不是指令子集&quot;">​</a></h3><p>没有哪条 RISC-V 指令强制 <code>sp</code> 16 字节对齐；AAPCS64 与 psABI 写了。违反时硬件可能仍执行，直到 SIMD spill 或系统调用入口检查失败。<a href="/cs/riscv-compressed">压缩</a> 是否存在，改变的是目标三元组，不是 opcode 合法性本身。</p><p><span class="marginnote">SysV AMD64 ABI；RISC-V ELF psABI；AAPCS64。Patterson/Hennessy 用调用例子连接组成与软件。本课不抄整张寄存器角色表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译与链接选定三元组：<code>riscv64-linux-gnu</code> 意味着 LP64、小端、特定系统调用。代码生成遵守合同；手写汇编同样。上下文切换保存 ISA 状态（GPR、<a href="/cs/simd-extensions">SIMD</a> 宽寄存器、<a href="/cs/rvv-vector">RVV</a> <code>v</code> 与 <code>vl</code>），其布局又是内核 ABI。用户程序看不见 <code>hgatp</code>，那是 H 扩展的特权面，不进入 psABI。</p>',11)),(e(),t(l,null,{default:s(()=>[A(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ISA%5B%22ISA%EF%BC%9A%E7%BC%96%E7%A0%81%E4%B8%8E%E5%BC%82%E5%B8%B8%22%5D%20--%3E%20ABI%5B%22ABI%EF%BC%9A%E5%AF%84%E5%AD%98%E5%99%A8%E8%A7%92%E8%89%B2%E4%B8%8E%E5%AF%B9%E9%BD%90%22%5D%0A%20%20ABI%20--%3E%20OBJ%5B%22%E5%8F%AF%E9%93%BE%E6%8E%A5%E7%9B%AE%E6%A0%87%E6%96%87%E4%BB%B6%22%5D%0A%20%20OBJ%20--%3E%20RUN%5B%22%E4%B8%8E%20libc%20%E4%BA%92%E8%B0%83%22%5D%0A%20%20RUN%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%89%8D%E7%AB%AF%E9%A2%84%E6%B5%8B%E8%BF%99%E4%BA%9B%E5%88%86%E6%94%AF%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>系统调用是另一条边界：<code>ecall</code>/<code>syscall</code>/<code>svc</code> 是 ISA；号与参数槽是 OS ABI，本课点名即止。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>数字系统与接口的 ISA 对照在此封口：后课不再换指令集哲学，而是假定一份已冻结的用户可见 ISA+ABI，问微结构如何把它跑快。下一课起是<a href="/cs/gshare-predictor">微结构进阶</a>：组成课已经用饱和计数器猜方向；现在要处理相关分支——ISA 只定义 <code>beq</code> 是否跳，不定义前端如何猜。gshare 从这里接过。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整 psABI 附录，不比较发行版动态链接器。不把 Windows / Linux 的系统调用表当 ISA。不进入量化策略的 FFI。</p><p>后课默认：能互调的程序共享 ABI；ISA 只保证单颗核如何执行指令。下一课 gshare 预测器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ISA 是硬件合同；ABI 是软件互调合同。</li><li>同一 ISA 可有多份 ABI；扩展集写进目标三元组。</li><li>本单元对照结束，微结构进阶从分支预测开始。</li><li>出处：SysV ABI；RISC-V ELF psABI；AAPCS64；Patterson and Hennessy, COD。</li></ul>',8))])}const _=c(B,[["render",I]]);export{f as __pageData,_ as default};
